"""Finalize completed API loops and validate exact generated bytes; no API calls."""
from datetime import datetime, timezone
import hashlib
from pathlib import Path

import claude_p30 as runner
import adapter


def main():
    root = runner.ROOT
    before = root / "validation_audit/adapter.before_validation_fix.py"
    trajectories = list((root / "runs/sonnet5.5p30/tasks").glob("*/traj.json")) + list((root / "runs/haiku5p30/tasks").glob("*/traj.json"))
    if len(trajectories) != 60:
        raise ValueError("All 60 agent loops must have completed before finalization")
    for trajectory in trajectories:
        data = adapter.read_json(trajectory)
        if data["messages"][-1].get("role") != "exit":
            raise ValueError("Agent loop has not terminated: " + str(trajectory))
    ended = datetime.fromtimestamp(max(path.stat().st_mtime for path in trajectories), timezone.utc).isoformat()
    receipt = {"file": "adapter.py", "before_sha256": adapter.sha(before), "after_sha256": adapter.sha(root / "adapter.py"),
               "applied_at_utc": datetime.now(timezone.utc).isoformat(), "agent_phase_completed_at_utc": ended,
               "scope_functions": ["snapshot_candidate", "validate_task"], "runtime_environment_unchanged": True,
               "reason": "Preserve API-generated bytes through Windows snapshotting; represent a deleted candidate as missing/failed, without restoring or repairing it",
               "before_source_path": str(before.resolve())}
    adapter.write_json(root / "validation_audit/receipt.json", receipt)
    for spec in runner.SPECS:
        run = root / "runs" / spec["folder"]
        manifest = adapter.read_json(run / "manifest.json")
        if manifest["runner_sources"]["adapter.py"] != receipt["before_sha256"]:
            raise ValueError("Original adapter generation provenance changed")
        manifest["validation_adjustments"] = [receipt]
        adapter.write_json(run / "manifest.json", manifest)
        for task in manifest["tasks"]:
            tdir = run / "tasks" / task["case"]
            result_path = tdir / "agent_result.json"
            if result_path.exists():
                continue
            # The only incomplete artifact was an already-terminated loop whose
            # repair target was deleted. Its final candidate is a deletion.
            traj = adapter.read_json(tdir / "traj.json")
            if (tdir / "workspace/buggy.py").exists() or traj["info"]["exit_status"] != "LimitsExceeded":
                raise ValueError("Unexpected result recovery case: " + task["case"])
            stats = traj["info"]["model_stats"]
            adapter.write_json(result_path, {"case": task["case"], "version": task["version"], "model": spec["model"],
                                            "exit_status": "LimitsExceeded", "error": "Agent deleted buggy.py before reaching the 40-call limit",
                                            "steps": stats["api_calls"], "cost_usd": round(stats["instance_cost"], 8), "seconds": None,
                                            "submitted": False, "candidate_test_feedback": False, "candidate_present": False,
                                            "original_script_returncode": traj["environment_commands"][0]["returncode"],
                                            "candidate_sha256": hashlib.sha256(b"").hexdigest(),
                                            "recovered_from_completed_trajectory": True})
            (tdir / "patched.py").write_bytes(b"")
        adapter.validate_all(run, workers=3, timeout=120)
    comparison = runner.save_summaries(runner.SPECS)
    print(comparison, flush=True)


if __name__ == "__main__":
    main()
